		t.Fatalf("oauth credential mismatch: %+v", got)
	}
	if got.Expires != 1730000000 {
		t.Fatalf("expires = %d, want 1730000000", got.Expires)
	}
	if got.Extra["account_id"] != "acc-1" {
		t.Fatalf("extra mismatch: %+v", got.Extra)
	}
}

